void CVoiceChangerDlg::FillDevices(){AudioMicDevRefresh();m_mic.ResetContent();int sel=0;m_micCnt=0;for(int i=0;i<AudioMicDevCount()&&m_micCnt<VC_MAX;i++){LPCTSTR id=AudioMicDevId(i);if(!id||!*id)continue;_tcsncpy(m_micIds[m_micCnt],id,255);m_micIds[m_micCnt][255]=0;m_mic.AddString(AudioMicDevName(i));if(!_tcsicmp(id,savedata.vc_mic_device))sel=m_micCnt;m_micCnt++;}if(m_micCnt)m_mic.SetCurSel(sel);AudioLoopDevRefresh();m_out.ResetContent();sel=0;m_outCnt=0;for(int i=0;i<AudioLoopDevCount()&&m_outCnt<VC_MAX;i++){LPCTSTR id=AudioLoopDevId(i);if(!id||!*id)continue;_tcsncpy(m_outIds[m_outCnt],id,255);m_outIds[m_outCnt][255]=0;m_out.AddString(AudioLoopDevName(i));if(!_tcsicmp(id,savedata.vc_out_device))sel=m_outCnt;m_outCnt++;}if(m_outCnt)m_out.SetCurSel(sel);}
void CVoiceChangerDlg::FillValues(){static const int v[]={50,60,70,80,90,100,110,120,130,140,150,175,200};CCustomComboBox*c[]={&m_pitch,&m_form,&m_gain};int vals[]={savedata.vc_pitch,savedata.vc_formant,savedata.vc_gain};for(int k=0;k<3;k++){for(int i=0;i<_countof(v);i++){CString x;x.Format(L"%d%%",v[i]);c[k]->AddString(x);if(v[i]==vals[k])c[k]->SetCurSel(i);}if(c[k]->GetCurSel()<0)c[k]->SetCurSel(5);}for(int i=0;i<5;i++)m_preset.AddString(VcPresetName(i));m_preset.SetCurSel(max(0,min(4,savedata.vc_preset)));m_monitor.SetCheck(savedata.vc_monitor?BST_CHECKED:BST_UNCHECKED);}
void CVoiceChangerDlg::PersistUi(){int i=m_mic.GetCurSel();if(i>=0&&i<m_micCnt)_tcsncpy(savedata.vc_mic_device,m_micIds[i],255);savedata.vc_mic_device[255]=0;i=m_out.GetCurSel();if(i>=0&&i<m_outCnt)_tcsncpy(savedata.vc_out_device,m_outIds[i],255);savedata.vc_out_device[255]=0;static const int v[]={50,60,70,80,90,100,110,120,130,140,150,175,200};savedata.vc_pitch=v[max(0,min(12,m_pitch.GetCurSel()))];savedata.vc_formant=v[max(0,min(12,m_form.GetCurSel()))];savedata.vc_gain=v[max(0,min(12,m_gain.GetCurSel()))];savedata.vc_monitor=m_monitor.GetCheck()==BST_CHECKED;savedata.vc_preset=max(0,min(4,m_preset.GetCurSel()));MpPersistSavedataQuick();}
void CVoiceChangerDlg::ApplyPreset(int n){static const int p[5][3]={{100,100,100},{75,75,110},{135,130,90},{90,160,115},{105,60,130}};static const int v[]={50,60,70,80,90,100,110,120,130,140,150,175,200};n=max(0,min(4,n));for(int k=0;k<3;k++){CCustomComboBox*c=k==0?&m_pitch:k==1?&m_form:&m_gain;int best=0;for(int i=1;i<13;i++)if(abs(v[i]-p[n][k])<abs(v[best]-p[n][k]))best=i;c->SetCurSel(best);}m_preset.SetCurSel(n);PersistUi();}
