BOOL CVoiceChangerDlg::StartAudio(){PersistUi();if(savedata.mpMirrorOut&&savedata.mpMirrorDevice[0]&&!_tcsicmp(savedata.vc_out_device,savedata.mpMirrorDevice)){MessageBox(LL14(L"選択出力はメディアプレイヤーのミラー出力で使用中です。",L"The selected output is already used by media-player mirroring.",L"La sortie est utilisée par le miroir du lecteur.",L"L'uscita è usata dal mirror del lettore.",L"La salida está usada por el espejo del reproductor.",L"선택 출력은 미디어 플레이어 미러에서 사용 중입니다.",L"所选输出正被媒体播放器镜像使用。",L"الخرج مستخدم لنسخ مشغل الوسائط.",L"Выход занят зеркалированием проигрывателя.",L"Ausgang wird vom Player-Mirror verwendet.",L"A saída está em uso pelo espelho do leitor.",L"Uitvoer wordt gebruikt door speler-mirroring.",L"Wyjście jest używane przez mirror odtwarzacza.",L"Çıkış medya oynatıcı aynalamasında kullanılıyor."),LL14(L"出力競合",L"Output conflict",L"Conflit de sortie",L"Conflitto uscita",L"Conflicto de salida",L"출력 충돌",L"输出冲突",L"تعارض الخرج",L"Конфликт выхода",L"Ausgabekonflikt",L"Conflito de saída",L"Uitvoerconflict",L"Konflikt wyjścia",L"Çıkış çakışması"),MB_ICONWARNING);return FALSE;}m_pitchPct=savedata.vc_pitch;m_formPct=savedata.vc_formant;m_gainPct=savedata.vc_gain;m_monitorOn=savedata.vc_monitor;InterlockedExchange(&m_stop,0);InterlockedExchange(&m_lastHr,S_OK);uintptr_t t=_beginthreadex(NULL,0,AudioThread,this,0,NULL);if(!t)return FALSE;m_thread=(HANDLE)t;SetRunningUi(TRUE);SetTimer(VC_TIMER,50,NULL);m_status.SetWindowText(LL14(L"処理中…",L"Processing…",L"Traitement…",L"Elaborazione…",L"Procesando…",L"처리 중…",L"处理中…",L"جارٍ المعالجة…",L"Обработка…",L"Verarbeitung…",L"A processar…",L"Verwerken…",L"Przetwarzanie…",L"İşleniyor…"));return TRUE;}
void CVoiceChangerDlg::StopAudio(){InterlockedExchange(&m_stop,1);if(m_thread){WaitForSingleObject(m_thread,4000);CloseHandle(m_thread);m_thread=NULL;}InterlockedExchange(&m_run,0);if(GetSafeHwnd()){KillTimer(VC_TIMER);SetRunningUi(FALSE);}}
void CVoiceChangerDlg::OnStart(){if(m_thread)StopAudio();else StartAudio();}
void CVoiceChangerDlg::OnTimer(UINT_PTR id){if(id==VC_TIMER){LONG p=InterlockedCompareExchange(&m_peak,0,0);InterlockedExchange(&m_peak,p*85/100);m_meter.SetLevel(min(1000,(int)(sqrt((double)p/1000.0)*1100)));if(m_thread&&WaitForSingleObject(m_thread,0)==WAIT_OBJECT_0){HRESULT h=(HRESULT)InterlockedCompareExchange(&m_lastHr,0,0);CloseHandle(m_thread);m_thread=NULL;KillTimer(VC_TIMER);SetRunningUi(FALSE);CString x;x.Format(LL14(L"出力デバイスを初期化できません (0x%08X)。",L"Cannot initialize output device (0x%08X).",L"Impossible d'initialiser la sortie (0x%08X).",L"Impossibile inizializzare l'uscita (0x%08X).",L"No se puede inicializar la salida (0x%08X).",L"출력 장치를 초기화할 수 없습니다 (0x%08X).",L"无法初始化输出设备 (0x%08X)。",L"تعذر تهيئة جهاز الخرج (0x%08X).",L"Не удалось инициализировать выход (0x%08X).",L"Ausgabegerät nicht initialisierbar (0x%08X).",L"Não foi possível iniciar a saída (0x%08X).",L"Uitvoerapparaat kan niet initialiseren (0x%08X).",L"Nie można zainicjować wyjścia (0x%08X).",L"Çıkış aygıtı başlatılamıyor (0x%08X)."),(UINT)h);m_status.SetWindowText(x);}}CCustomBlurDialogBase::OnTimer(id);}
UINT __stdcall CVoiceChangerDlg::AudioThread(void*q){CVoiceChangerDlg*s=(CVoiceChangerDlg*)q;CoInitializeEx(NULL,COINIT_MULTITHREADED);IMMDeviceEnumerator*e=NULL;IMMDevice*mi=NULL,*od=NULL,*md=NULL;IAudioClient*cc=NULL,*oc=NULL,*mc=NULL;IAudioCaptureClient*cp=NULL;IAudioRenderClient*renOut=NULL,*mr=NULL;WAVEFORMATEX*f=NULL;UINT32 ob=0,mb=0;HRESULT h=CoCreateInstance(__uuidof(MMDeviceEnumerator),NULL,CLSCTX_ALL,__uuidof(IMMDeviceEnumerator),(void**)&e);if(SUCCEEDED(h))h=e->GetDevice(savedata.vc_mic_device,&mi);if(FAILED(h)&&e)h=e->GetDefaultAudioEndpoint(eCapture,eConsole,&mi);if(SUCCEEDED(h))h=mi->Activate(__uuidof(IAudioClient),CLSCTX_ALL,NULL,(void**)&cc);if(SUCCEEDED(h))h=cc->GetMixFormat(&f);if(SUCCEEDED(h))h=cc->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_NOPERSIST,2000000,0,f,NULL);if(SUCCEEDED(h))h=cc->GetService(__uuidof(IAudioCaptureClient),(void**)&cp);if(SUCCEEDED(h))h=e->GetDevice(savedata.vc_out_device,&od);if(FAILED(h)&&e)h=e->GetDefaultAudioEndpoint(eRender,eConsole,&od);if(SUCCEEDED(h))h=VcOpenRender(od,&oc,&renOut,&ob);if(SUCCEEDED(h)&&s->m_monitorOn){HRESULT z=e->GetDefaultAudioEndpoint(eRender,eConsole,&md);if(SUCCEEDED(z)){LPWSTR a=NULL,b=NULL;od->GetId(&a);md->GetId(&b);if(a&&b&&!_wcsicmp(a,b)){md->Release();md=NULL;}if(a)CoTaskMemFree(a);if(b)CoTaskMemFree(b);}if(md)h=VcOpenRender(md,&mc,&mr,&mb);}if(SUCCEEDED(h)){h=cc->Start();if(SUCCEEDED(h))h=oc->Start();if(SUCCEEDED(h)&&mc)h=mc->Start();}InterlockedExchange(&s->m_lastHr,h);if(FAILED(h))goto done;InterlockedExchange(&s->m_run,1);{float ring[16384]={};LONG w=4096;double rd=0,phase=0;float lp=0;short pcm[4096*2];while(!InterlockedCompareExchange(&s->m_stop,0,0)){UINT32 n=0;if(FAILED(cp->GetNextPacketSize(&n)))break;if(!n){Sleep(2);continue;}BYTE*d=NULL;DWORD fl=0;if(FAILED(cp->GetBuffer(&d,&n,&fl,NULL,NULL)))break;int made=0;while(phase<n&&made<4096){int ix=(int)phase;float l,r;if(fl&AUDCLNT_BUFFERFLAGS_SILENT)l=r=0;else VcRead(d+(SIZE_T)ix*f->nBlockAlign,f,l,r);float in=(l+r)*.5f;ring[w&16383]=in;w++;double want=w-2400+rd;int ri=((int)want)&16383;float x=ring[ri];rd+=s->m_pitchPct/100.0-1.0;if(rd>1800)rd-=1800;if(rd< -1800)rd+=1800;float alpha=.02f+(s->m_formPct/200.f)*.25f;lp+=alpha*(x-lp);x=x+(x-lp)*(s->m_formPct-100)/100.f;x=VcClamp(x*s->m_gainPct/100.f);pcm[made*2]=pcm[made*2+1]=(short)(x*32767);LONG pk=(LONG)(fabsf(x)*1000),old=InterlockedCompareExchange(&s->m_peak,0,0);if(pk>old)InterlockedExchange(&s->m_peak,pk);made++;phase+=f->nSamplesPerSec/48000.0;}phase-=n;cp->ReleaseBuffer(n);VcWrite(oc,renOut,ob,pcm,made);VcWrite(mc,mr,mb,pcm,made);}}done:if(cc)cc->Stop();if(oc)oc->Stop();if(mc)mc->Stop();if(mr)mr->Release();if(renOut)renOut->Release();if(cp)cp->Release();if(mc)mc->Release();if(oc)oc->Release();if(cc)cc->Release();if(md)md->Release();if(od)od->Release();if(mi)mi->Release();if(e)e->Release();if(f)CoTaskMemFree(f);InterlockedExchange(&s->m_run,0);CoUninitialize();return 0;}
void CVoiceChangerDlg::OnContextMenu(CWnd*,CPoint p){CCustomPopupMenu m;for(int i=0;i<5;i++)m.AddCheck(100+i,VcPresetName(i),m_preset.GetCurSel()==i);if(p.x<0){CRect r;GetWindowRect(r);p=r.TopLeft()+CPoint(40,40);}UINT c=m.Track(p,this);if(c>=100&&c<105&&!m_uiLocked)ApplyPreset(c-100);}
void CVoiceChangerDlg::ShowHelpSheet(){if(vcHelp&&vcHelp->GetSafeHwnd()){vcHelp->SetForegroundWindow();return;}vcHelp=new CVcHelp(this);if(!vcHelp->Create(IDD_VC_HELP,this)){delete vcHelp;vcHelp=NULL;return;}CCC_PresentOwnedHelp(this,vcHelp);}
void CVoiceChangerDlg::OnHelp(){ShowHelpSheet();}void CVoiceChangerDlg::OnCloseBtn(){DestroyWindow();}void CVoiceChangerDlg::OnOK(){}void CVoiceChangerDlg::OnCancel(){DestroyWindow();}void CVoiceChangerDlg::OnSize(UINT t,int x,int y){CCustomBlurDialogBase::OnSize(t,x,y);if(GetSafeHwnd()){CCC_CaptionLayout(m_hWnd);LayoutHelpBtn();}}void CVoiceChangerDlg::OnDestroy(){PersistUi();StopAudio();CCustomBlurDialogBase::OnDestroy();}
